#!/usr/bin/env python3
"""
Header and Script Exporter for RBX-Finder
Generates C++ headers, JSON maps, Ghidra annotations, and Frida hooks.
"""
from __future__ import annotations

import json
from pathlib import Path
from symbol_resolver import ResolvedProfile


class HeaderGenerator:

    @staticmethod
    def emit_build_profile_hpp(profile: ResolvedProfile, out_path: Path):
        """
        Emits build_profile.hpp matching the ORC/Xecutor profile format.
        """
        lines = [
            "#pragma once",
            "// Auto-generated by RBX-Finder Automated Offset Dumper",
            f"// Engine Build ID: {profile.engine_build_id}",
            f"// Target Arch: {profile.target_arch}",
            "",
            "#include <cstdint>",
            "#include <cstddef>",
            "",
            "namespace profile {",
            f"inline constexpr char expected_build_id[] = \"{profile.engine_build_id}\";",
            f"inline constexpr std::size_t base_identity = {profile.struct_offsets.get('base_identity', 3)};",
            f"inline constexpr std::size_t execution_identity = {profile.struct_offsets.get('execution_identity', 8)};",
            "",
            "// Structure Offsets",
        ]

        for k, v in sorted(profile.struct_offsets.items()):
            if k in ("base_identity", "execution_identity"):
                continue
            lines.append(f"inline constexpr std::uintptr_t {k} = 0x{v:x};")

        lines.extend([
            "",
            "// Core Function Offsets",
        ])

        for k, v in sorted(profile.functions.items()):
            lines.append(f"inline constexpr std::uintptr_t {k} = 0x{v:x};")

        lines.extend([
            "} // namespace profile",
            ""
        ])

        out_path.write_text("\n".join(lines), encoding="utf-8")

    @staticmethod
    def emit_frida_script(profile: ResolvedProfile, out_path: Path):
        """
        Emits a Frida hook script ready to attach to com.roblox.client.
        """
        lines = [
            "// Frida hook script — auto-generated by RBX-Finder",
            "'use strict';",
            "",
            "const MODULE_NAME = 'libroblox.so';",
            "",
            "function hook() {",
            "    const base = Module.findBaseAddress(MODULE_NAME);",
            "    if (!base) {",
            "        console.log('[*] Waiting for ' + MODULE_NAME + '...');",
            "        setTimeout(hook, 200);",
            "        return;",
            "    }",
            "    console.log('[+] ' + MODULE_NAME + ' loaded at ' + base);",
            "",
        ]

        for fn_name, off in sorted(profile.functions.items()):
            lines.extend([
                f"    // {fn_name} @ 0x{off:x}",
                f"    const addr_{fn_name} = base.add(0x{off:x});",
                f"    Interceptor.attach(addr_{fn_name}, {{",
                f"        onEnter: function(args) {{",
                f"            console.log('[CALL] {fn_name}');",
                f"        }}",
                f"    }});",
                "",
            ])

        lines.extend([
            "    console.log('[+] All hooks installed successfully!');",
            "}",
            "",
            "setImmediate(hook);",
            ""
        ])

        out_path.write_text("\n".join(lines), encoding="utf-8")

    @staticmethod
    def emit_json(profile: ResolvedProfile, out_path: Path):
        data = {
            "engine_build_id": profile.engine_build_id,
            "target_arch": profile.target_arch,
            "functions": {k: f"0x{v:x}" for k, v in sorted(profile.functions.items())},
            "functions_raw": profile.functions,
            "struct_offsets": {k: f"0x{v:x}" for k, v in sorted(profile.struct_offsets.items())},
            "raw_xrefs": {k: [f"0x{x:x}" for x in v] for k, v in sorted(profile.raw_xrefs.items())},
            "confidence": profile.confidence
        }
        out_path.write_text(json.dumps(data, indent=2), encoding="utf-8")
